begin;
create extension if not exists pgtap with schema extensions;
set search_path = public, extensions;
select no_plan();
insert into auth.users(id,email) values ('11111111-1111-4111-8111-111111111111','alice@daywise.test'),('22222222-2222-4222-8222-222222222222','bob@daywise.test');
create function pg_temp.denied(q text) returns boolean language plpgsql as $$
begin execute q; return false;
exception when insufficient_privilege or foreign_key_violation or unique_violation then return true;
end $$;
set local role authenticated;
select set_config('request.jwt.claim.sub','11111111-1111-4111-8111-111111111111',true);
insert into profiles(id,"displayName") values('alice','Alice');
select daywise_income('alice','2026-10',100001,'default');
select daywise_commitment('{"id":"bill-a","profileId":"alice","yearMonth":"2026-10","name":"Rent","category":"Rent","amountMinor":20003,"origin":"recurring","paid":true,"notes":""}','future');
insert into daily_expenses(id,"profileId",date,"amountMinor",category,description) values('expense-a','alice','2026-10-01',101,'Coffee','Coffee');
insert into categories(id,"profileId",name,type) values('category-a','alice','Craft','daily');
insert into local_migrations(source_profile,profile_id,fingerprint,manifest) values('local-a','alice',repeat('a',64),'{}');
select set_config('request.jwt.claim.sub','22222222-2222-4222-8222-222222222222',true);
insert into profiles(id,"displayName") values('bob','Bob');
select daywise_income('bob','2026-10',50000,'default');
select ok((select relrowsecurity and relforcerowsecurity from pg_class where oid='public.profiles'::regclass),'profiles forces RLS');
