with removed as (delete from profiles where owner_id='11111111-1111-4111-8111-111111111111' returning 1) select is((select count(*) from removed),0::bigint,'Bob cannot delete Alice profiles');
select ok((select relrowsecurity and relforcerowsecurity from pg_class where oid='public.income_revisions'::regclass),'income_revisions forces RLS');
select is((select count(*) from income_revisions where owner_id='11111111-1111-4111-8111-111111111111'),0::bigint,'Bob cannot select Alice income_revisions');
