with removed as (delete from recurring_sources where owner_id='11111111-1111-4111-8111-111111111111' returning 1) select is((select count(*) from removed),0::bigint,'Bob cannot delete Alice recurring_sources');
select ok((select relrowsecurity and relforcerowsecurity from pg_class where oid='public.recurring_revisions'::regclass),'recurring_revisions forces RLS');
select is((select count(*) from recurring_revisions where owner_id='11111111-1111-4111-8111-111111111111'),0::bigint,'Bob cannot select Alice recurring_revisions');
with changed as (update recurring_revisions set owner_id='22222222-2222-4222-8222-222222222222' where owner_id='11111111-1111-4111-8111-111111111111' returning 1) select is((select count(*) from changed),0::bigint,'Bob cannot update Alice recurring_revisions');
with removed as (delete from recurring_revisions where owner_id='11111111-1111-4111-8111-111111111111' returning 1) select is((select count(*) from removed),0::bigint,'Bob cannot delete Alice recurring_revisions');
select ok((select relrowsecurity and relforcerowsecurity from pg_class where oid='public.monthly_plans'::regclass),'monthly_plans forces RLS');
select is((select count(*) from monthly_plans where owner_id='11111111-1111-4111-8111-111111111111'),0::bigint,'Bob cannot select Alice monthly_plans');
with changed as (update monthly_plans set owner_id='22222222-2222-4222-8222-222222222222' where owner_id='11111111-1111-4111-8111-111111111111' returning 1) select is((select count(*) from changed),0::bigint,'Bob cannot update Alice monthly_plans');
with removed as (delete from monthly_plans where owner_id='11111111-1111-4111-8111-111111111111' returning 1) select is((select count(*) from removed),0::bigint,'Bob cannot delete Alice monthly_plans');
select ok((select relrowsecurity and relforcerowsecurity from pg_class where oid='public.monthly_commitments'::regclass),'monthly_commitments forces RLS');
select is((select count(*) from monthly_commitments where owner_id='11111111-1111-4111-8111-111111111111'),0::bigint,'Bob cannot select Alice monthly_commitments');
with changed as (update monthly_commitments set owner_id='22222222-2222-4222-8222-222222222222' where owner_id='11111111-1111-4111-8111-111111111111' returning 1) select is((select count(*) from changed),0::bigint,'Bob cannot update Alice monthly_commitments');
with removed as (delete from monthly_commitments where owner_id='11111111-1111-4111-8111-111111111111' returning 1) select is((select count(*) from removed),0::bigint,'Bob cannot delete Alice monthly_commitments');
select ok((select relrowsecurity and relforcerowsecurity from pg_class where oid='public.daily_expenses'::regclass),'daily_expenses forces RLS');
select is((select count(*) from daily_expenses where owner_id='11111111-1111-4111-8111-111111111111'),0::bigint,'Bob cannot select Alice daily_expenses');
with changed as (update daily_expenses set owner_id='22222222-2222-4222-8222-222222222222' where owner_id='11111111-1111-4111-8111-111111111111' returning 1) select is((select count(*) from changed),0::bigint,'Bob cannot update Alice daily_expenses');
with removed as (delete from daily_expenses where owner_id='11111111-1111-4111-8111-111111111111' returning 1) select is((select count(*) from removed),0::bigint,'Bob cannot delete Alice daily_expenses');
select ok((select relrowsecurity and relforcerowsecurity from pg_class where oid='public.categories'::regclass),'categories forces RLS');
select is((select count(*) from categories where owner_id='11111111-1111-4111-8111-111111111111'),0::bigint,'Bob cannot select Alice categories');
with changed as (update categories set owner_id='22222222-2222-4222-8222-222222222222' where owner_id='11111111-1111-4111-8111-111111111111' returning 1) select is((select count(*) from changed),0::bigint,'Bob cannot update Alice categories');
