select is((select count(*) from local_migrations where owner_id='11111111-1111-4111-8111-111111111111'),0::bigint,'Bob cannot select Alice local_migrations');
select ok(pg_temp.denied('update local_migrations set source_profile=''tampered'''),'Receipts cannot be modified');
select ok(pg_temp.denied('delete from local_migrations'),'Receipts cannot be deleted');
select ok(pg_temp.denied($q$update profiles set owner_id='11111111-1111-4111-8111-111111111111' where id='bob'$q$),'Cannot change ownership');
select ok(pg_temp.denied($q$insert into daily_expenses("profileId",date,"amountMinor",category,description) values('alice','2026-10-01',1,'x','x')$q$),'Cannot reference another user workspace');
select ok(pg_temp.denied($q$select daywise_export('alice')$q$),'Cannot export another user');
select ok(pg_temp.denied($q$select daywise_month('alice','2026-10')$q$),'Cannot materialize another user month');
select ok(pg_temp.denied($q$select daywise_income('alice','2026-10',999,'default')$q$),'Cannot revise another user income');
select ok(pg_temp.denied($q$select daywise_paid('alice','bill-a')$q$),'Cannot mark another user payment');
select ok(pg_temp.denied($q$select daywise_remove('alice','bill-a',true)$q$),'Cannot remove another user bill');
select ok(pg_temp.denied($q$select daywise_import('{}','local-a',repeat('a',64),'{}','11111111-1111-4111-8111-111111111111')$q$),'Import bound to verified owner');
select lives_ok($q$select daywise_export('bob')$q$,'Own export works');
reset role;
-- Capture Alice's valid row shapes before testing forged INSERT for every table.
create temp table fixtures(table_name text, payload jsonb);
insert into fixtures select 'profiles',to_jsonb(t) from profiles t where owner_id='11111111-1111-4111-8111-111111111111' limit 1;
insert into fixtures select 'income_revisions',to_jsonb(t) from income_revisions t where owner_id='11111111-1111-4111-8111-111111111111' limit 1;
insert into fixtures select 'recurring_sources',to_jsonb(t) from recurring_sources t where owner_id='11111111-1111-4111-8111-111111111111' limit 1;
insert into fixtures select 'recurring_revisions',to_jsonb(t) from recurring_revisions t where owner_id='11111111-1111-4111-8111-111111111111' limit 1;
insert into fixtures select 'monthly_plans',to_jsonb(t) from monthly_plans t where owner_id='11111111-1111-4111-8111-111111111111' limit 1;
insert into fixtures select 'monthly_commitments',to_jsonb(t) from monthly_commitments t where owner_id='11111111-1111-4111-8111-111111111111' limit 1;
insert into fixtures select 'daily_expenses',to_jsonb(t) from daily_expenses t where owner_id='11111111-1111-4111-8111-111111111111' limit 1;
insert into fixtures select 'categories',to_jsonb(t) from categories t where owner_id='11111111-1111-4111-8111-111111111111' limit 1;
insert into fixtures select 'local_migrations',to_jsonb(t) from local_migrations t where owner_id='11111111-1111-4111-8111-111111111111' limit 1;
grant select on fixtures to authenticated;
set local role authenticated;
select ok(pg_temp.denied(format('insert into public.%I select (jsonb_populate_record(null::public.%I,%L)).*','profiles','profiles',(select payload || '{"id":"forged-profiles"}'::jsonb from fixtures where table_name='profiles'))),'Forged owner INSERT denied for profiles');
select ok(pg_temp.denied(format('insert into public.%I select (jsonb_populate_record(null::public.%I,%L)).*','income_revisions','income_revisions',(select payload || '{"id":"forged-income_revisions"}'::jsonb from fixtures where table_name='income_revisions'))),'Forged owner INSERT denied for income_revisions');
select ok(pg_temp.denied(format('insert into public.%I select (jsonb_populate_record(null::public.%I,%L)).*','recurring_sources','recurring_sources',(select payload || '{"id":"forged-recurring_sources"}'::jsonb from fixtures where table_name='recurring_sources'))),'Forged owner INSERT denied for recurring_sources');
select ok(pg_temp.denied(format('insert into public.%I select (jsonb_populate_record(null::public.%I,%L)).*','recurring_revisions','recurring_revisions',(select payload || '{"id":"forged-recurring_revisions"}'::jsonb from fixtures where table_name='recurring_revisions'))),'Forged owner INSERT denied for recurring_revisions');
select ok(pg_temp.denied(format('insert into public.%I select (jsonb_populate_record(null::public.%I,%L)).*','monthly_plans','monthly_plans',(select payload || '{"id":"forged-monthly_plans"}'::jsonb from fixtures where table_name='monthly_plans'))),'Forged owner INSERT denied for monthly_plans');
select ok(pg_temp.denied(format('insert into public.%I select (jsonb_populate_record(null::public.%I,%L)).*','monthly_commitments','monthly_commitments',(select payload || '{"id":"forged-monthly_commitments"}'::jsonb from fixtures where table_name='monthly_commitments'))),'Forged owner INSERT denied for monthly_commitments');
select ok(pg_temp.denied(format('insert into public.%I select (jsonb_populate_record(null::public.%I,%L)).*','daily_expenses','daily_expenses',(select payload || '{"id":"forged-daily_expenses"}'::jsonb from fixtures where table_name='daily_expenses'))),'Forged owner INSERT denied for daily_expenses');
select ok(pg_temp.denied(format('insert into public.%I select (jsonb_populate_record(null::public.%I,%L)).*','categories','categories',(select payload || '{"id":"forged-categories"}'::jsonb from fixtures where table_name='categories'))),'Forged owner INSERT denied for categories');
select ok(pg_temp.denied(format('insert into public.%I select (jsonb_populate_record(null::public.%I,%L)).*','local_migrations','local_migrations',(select payload || '{"id":"forged-local_migrations"}'::jsonb from fixtures where table_name='local_migrations'))),'Forged owner INSERT denied for local_migrations');
reset role;
set local role anon;
select set_config('request.jwt.claim.sub','',true);
select ok(pg_temp.denied('select * from public.profiles'),'Anonymous cannot read profiles');
select ok(pg_temp.denied('insert into public.profiles default values'),'Anonymous cannot insert profiles');
select ok(pg_temp.denied('update public.profiles set owner_id=null'),'Anonymous cannot update profiles');
