select ok(pg_temp.denied('update public.recurring_revisions set owner_id=null'),'Anonymous cannot update recurring_revisions');
select ok(pg_temp.denied('delete from public.recurring_revisions'),'Anonymous cannot delete recurring_revisions');
select ok(pg_temp.denied('select * from public.monthly_plans'),'Anonymous cannot read monthly_plans');
select ok(pg_temp.denied('insert into public.monthly_plans default values'),'Anonymous cannot insert monthly_plans');
select ok(pg_temp.denied('update public.monthly_plans set owner_id=null'),'Anonymous cannot update monthly_plans');
select ok(pg_temp.denied('delete from public.monthly_plans'),'Anonymous cannot delete monthly_plans');
