select ok(pg_temp.denied($q$select daywise_export('alice')$q$),'Anonymous cannot execute daywise_export');
select ok(pg_temp.denied($q$select daywise_month('alice','2026-10')$q$),'Anonymous cannot execute daywise_month');
select ok(pg_temp.denied($q$select daywise_income('alice','2026-10',1,'month')$q$),'Anonymous cannot execute daywise_income');
select ok(pg_temp.denied($q$select daywise_paid('alice','bill-a')$q$),'Anonymous cannot execute daywise_paid');
select ok(pg_temp.denied($q$select daywise_remove('alice','bill-a',true)$q$),'Anonymous cannot execute daywise_remove');
